install(9,[C('A','입력 A',0,1,1,0),C('B','입력 B',0,1,1,0),S('representation','회로 표현',[[0,'스위치'],[1,'트랜지스터']],0),B('current','전류',1)],v=>{let svg='',metrics=[];for(let k=0;k<3;k++){const x=130+k*260,type=['AND','OR','NOT'][k],out=k===0?v.A&v.B:k===1?v.A|v.B:1-v.A;let g=text(x,35,type,23)+text(x,66,'+V',19,red)+line(x,75,x,100)+(k===2?resistor(x,125,50,true):line(x,100,x,150))+line(x,150,x,175)+(k===2?line(x,325,x,355)+ground(x,355):line(x,325,x,337)+resistor(x,362,50,true)+line(x,387,x,392)+ground(x,392));const input=(xx,yy,key)=>v.representation?button(key,`입력 ${key} 전환`,dot(xx,yy,25,'#e4ebdf')+line(xx-10,yy-15,xx-10,yy+15,ink,3)+line(xx-10,yy-10,xx,yy-30)+arrow(xx-10,yy+10,xx,yy+30,+v[key]?green:ink,2)+line(xx-30,yy,xx-10,yy)+text(xx-43,yy+5,key,16,blue)):sw(xx,yy,+v[key],key,true);if(k===0)g+=line(x,175,x,185)+input(x,215,'A')+line(x,245,x,250)+input(x,280,'B')+line(x,310,x,325);if(k===1)g+=line(x-45,175,x+45,175)+line(x-45,175,x-45,215)+line(x+45,175,x+45,215)+input(x-45,245,'A')+input(x+45,245,'B')+line(x-45,275,x-45,325)+line(x+45,275,x+45,325)+line(x-45,325,x+45,325);if(k===2)g+=line(x,175,x,240)+input(x,270,'A')+line(x,300,x,325);const oy=k===2?190:325;g+=arrow(x,oy,x+75,oy,out?blue:wire)+text(x+87,oy+7,out,26,blue)+text(x,441,`A ${v.A}${k===2?'':` · B ${v.B}`}`,16);if(+v.current&&out)g+=arrow(x+35,oy,x+62,oy,red,3);svg+=panel(`logic-${type}`,g);metrics.push(metric(type,out));}return{svg,metrics,explanation:'AND는 두 직렬 스위치, OR은 두 병렬 스위치, NOT은 출력 아래의 스위치로 같은 입력을 비교합니다.',question:'A만1이고 B가0일 때 세 출력은?',answer:'AND0, OR1, NOT0입니다.',note:'세 회로를 동시에 표시한 이상적 스위치 모형입니다. 회로 속 스위치나 입력 조절기로 변경할 수 있습니다. 트랜지스터 표시는 기능 대응이며 실제 바이어스 회로의 수치는 생략했습니다.'};});
