install(11,[B('connection','연결 스위치',0),...M[11].controls.filter(c=>c.key!=='mode')],(v,t,r)=>{const dx=12*v.amplitude*Math.sin(TAU*v.frequency*t),draw=(cx,left)=>{const move=left?dx:+v.connection?dx:0;return panel(left?'microphone':'speaker',text(cx,55,left?'마이크':'스피커',23)+box(cx-62,160,124,50,'#d4e3e4',wire)+box(cx-62,160,62,50,left?red:blue,'none',0)+box(cx,160,62,50,left?blue:red,'none',0)+text(cx-30,192,left?'N':'S',21,'white')+text(cx+30,192,left?'S':'N',21,'white')+coil(cx+move,185,150)+path(left?`M${cx-90+move} 100L${cx-55+move} 150V220L${cx-90+move} 270Z`:`M${cx+90+move} 100L${cx+55+move} 150V220L${cx+90+move} 270Z`,gold,3,'#e4b97f')+line(cx-40,208,cx-40,320)+line(cx+40,208,cx+40,350));};let svg=draw(180,true)+draw(620,false)+line(220,350,660,350)+line(140,320,375,320)+sw(400,320,+v.connection,'connection')+line(425,320,580,320)+text(400,400,+v.connection?'진동 → 유도 신호 → 진동':'연결 스위치를 닫아 두 진동판을 비교',19);return {...r,svg,note:r.note+' 마이크 왼쪽·스피커 오른쪽의 서로 반대 극성과 두 연결선을 유지했습니다. 실제 마이크 입력은 별도 동의 버튼으로만 켜집니다.'};});
