install(16,[B('AM','AM 표시',1),B('FM','FM 표시',1),...M[16].controls.filter(c=>c.key!=='mode')],(v,t,r)=>{const msg=x=>Math.sin(TAU*x),am=x=>(1+v.depth*msg(x))/2*Math.sin(TAU*v.carrier*x),fm=x=>Math.sin(TAU*v.carrier*x+v.depth*3*Math.sin(TAU*x));let svg=panel('audio-source',text(130,105,'오디오 신호',19)+trace(35,175,190,45,msg,red)+dot(115,285,22,'#d2b696')+path('M115 308V370M115 325L155 350M115 325L80 340M115 370L85 410M115 370L145 410',wire,8)+dot(165,355,28,'#d5ae76')+line(165,350,205,290,gold,9))+arrow(240,175,310,125,red)+arrow(240,175,310,315,red);if(+v.AM)svg+=panel('AM-wave',text(490,70,'AM · 진폭 변조',20)+trace(330,135,300,55,am,blue,550)+trace(330,135,300,55,x=>(1+v.depth*msg(x))/2,gold));if(+v.FM)svg+=panel('FM-wave',text(490,250,'FM · 주파수 변조',20)+trace(330,315,300,55,fm,blue,550));svg+=panel('radio-mast',path('M705 115L680 390M705 115L730 390M690 280H720M686 325H724',wire,4)+dot(705,115,8,red)+path('M680 88Q650 115 680 142M730 88Q760 115 730 142',red,2));return {...r,svg,metrics:[metric('변조 지수',fmt(v.depth)),metric('주파수비',v.carrier)],explanation:'왼쪽의 같은 신호가 위쪽 AM의 포락선과 아래쪽 FM의 파형 간격에 각각 담깁니다.',note:'동시 비교를 위해 정보 신호 한 주기를 정규화해 그렸습니다. AM 과변조는 제외하고 FM 위상 편이 진폭은 표시 지수의3배입니다.'};});
// 17: four LED/inductor applications; lower switches and resistor remain spatially aligned.
install(17,[C('speed','관찰 속도',.1,3,.1,1),C('L','인덕턴스',10,1000,10,200,'mH'),C('R','저항',10,300,10,100,'Ω'),C('elapsed','스위치 동작 후 시간',0,500,1,2,'ms'),...Array.from({length:4},(_,i)=>B('s'+i,`${i+1}번 회로 스위치`,1))],(v,t,r)=>{let svg='',metrics=[],tau=v.L/v.R,e=Math.exp(-v.elapsed*v.speed/tau);for(let k=0;k<4;k++){let x=105+k*195,on=+v['s'+k],forward=on?(k===0?1-e:.5*Math.exp(-v.elapsed*v.speed/(2*tau))):0,reverse=!on?e:0;let g=text(x,33,'+V',18,red)+line(x,43,x,75)+line(x,245,x,268)+sw(x,292,on,'s'+k,true)+line(x,315,x,335)+resistor(x,360,50,true)+line(x,385,x,389)+ground(x,389)+text(x,438,['직렬 L','LED ∥ L','L ∥ 역방향 LED','양방향 표시'][k],15);if(k===0)g+=diode(x,110,true,false,forward)+line(x,140,x,155)+coil(x,200,90,true)+line(x,75,x,80);else{let xs=k===3?[x-55,x,x+55]:[x-42,x+42];g+=line(xs[0],75,xs.at(-1),75)+line(xs[0],245,xs.at(-1),245);for(let j=0;j<xs.length;j++){let xx=xs[j],isCoil=k===1?j===1:k===2?j===0:j===1;g+=line(xx,75,xx,120)+line(xx,200,xx,245)+(isCoil?coil(xx,160,80,true):diode(xx,160,true,k===2||j===2,k===2||j===2?reverse:forward));}}svg+=panel(`LED-circuit-${k+1}`,g);metrics.push(metric(`${k+1}번 정방향 LED`,fmt(forward*3/v.R*1000,3),'mA'));if(k>1)metrics.push(metric(`${k+1}번 역방향 LED`,fmt(reverse*3/v.R*1000,3),'mA'));}return {svg,metrics,question:'스위치를 열 때 반대 방향 LED가 켜지는 이유는?',answer:'코일이 기존 전류를 계속 흐르게 하면서 단자 전압이 반전되기 때문입니다.',explanation:'네 회로의 LED 방향과 코일의 위치를 나란히 비교합니다. 직렬 L의 지연, 닫을 때의 우회, 열 때의 역방향 점등을 비교할 수 있습니다.',note:'3V, LED 문턱0의 정성 비교 모형입니다. 시간은 각 스위치 동작 이후의 공통 관찰 시각입니다. 열림 상태는 충분히 충전된 코일에서 출발한 근사이며 실제 스위치 아크와 과전압은 재현하지 않습니다. 병렬 점등 가지는 유효 제한 저항 R을 포함한 등가 과도응답(τ=2L/R, 초기3/(2R))으로 계산합니다. 그림은 원본의 부품 위치를 보여 주는 기능도이며 내부 손실 저항을 모두 그린 제작용 회로도가 아닙니다. 밝기는 정규화 표시입니다.'};});
