// 59: source/feedline, vertical transmitting antenna, empty space, receiving antenna/load.
install(59,[C('zoom','줌',.7,1.2,.05,1),C('position','관찰 위치',-60,60,5,0),B('run','실행',0)],(v,t)=>{const q=Math.sin(TAU*.5*(+v.run?t:0)),qr=Math.sin(TAU*.5*(+v.run?t-1:0));let scene=panel('transmitter-source',dot(55,225,30,'#e7eeee')+`<circle cx="55" cy="225" r="30" fill="none" stroke="${wire}" stroke-width="3"/>`+text(55,235,'~',32)+line(55,195,55,205)+line(55,205,215,205)+line(55,255,55,245)+line(55,245,215,245));for(const [x,charge,label] of [[215,q,'송신'],[590,qr,'수신']]){scene+=panel(label==='송신'?'transmitting-dipole':'receiving-dipole',line(x,95,x,205,wire,7)+line(x,245,x,355,wire,7)+text(x,390,label+' 안테나',18));for(let j=0;j<8;j++){scene+=dot(x,108+j*12,4,j/8<Math.abs(charge)?charge>=0?red:blue:'#b4c6c9')+dot(x,260+j*12,4,j/8<Math.abs(charge)?charge>=0?blue:red:'#b4c6c9');}}scene+=panel('receiver-load',line(590,205,745,205)+line(590,245,745,245)+resistor(745,225,40,true)+text(725,290,'부하 R',16));if(+v.run)for(let k=0;k<9;k++){let radius=20+((t*60+k*52)%450);scene+=path(`M${215+radius*.55} ${225-radius*.65}Q${215+radius*1.2} 225 ${215+radius*.55} ${225+radius*.65}`,red,2);}return {svg:`<g transform="translate(${400+v.position} 225) scale(${v.zoom}) translate(-400 -225)">${scene}</g>`,metrics:[metric('작동',+v.run?'송신 중':'정지'),metric('안테나 편광','수직'),metric('줌',fmt(v.zoom),'배')],explanation:'왼쪽 교류 전원에서 두 도선을 따라 전달된 진동이 수직 송신 안테나에서 전파를 만듭니다. 오른쪽 수신 안테나의 전하가 반응하며 부하에 전류가 흐릅니다.',question:'두 안테나 사이에 연결선이 있나요?',answer:'없습니다. 빈 공간을 통해 전자기장의 변화가 전달됩니다. 도선의 전자가 빈 공간을 건너가는 것은 아닙니다.',note:'방사 파면과 전하 진동을 느리게 나타낸 정성 모형입니다. 줌과 위치는 관찰용이며 파장·거리의 실제 축척이 아닙니다.'};});
// 62: two corresponding loops with synchronized switch and separate current graphs above.
install(62,[...M[62].controls,B('switch','두 회로 공통 스위치',0),B('run','실행',1)],(v,t,r)=>{const tc=v.R*v.C*.001,tl=v.L/v.R,on=+v.switch,elapsed=+v.run?v.elapsed:0,il=5/v.R*(on?1-Math.exp(-elapsed/tl):Math.exp(-elapsed/tl)),ic=(on?1:-1)*5/v.R*Math.exp(-elapsed/tc),vc=5*(on?1-Math.exp(-elapsed/tc):Math.exp(-elapsed/tc));let svg='';for(let k=0;k<2;k++){let x=45+k*400,y=225;const current=k?ic:il,fn=s=>k?(on?1:-1)*Math.exp(-s*50/tc):on?1-Math.exp(-s*50/tl):Math.exp(-s*50/tl);let g=text(x+145,30,k?'커패시터 C':'인덕터 L',21)+plot(x+10,55,305,110,fn,red)+text(x+160,185,'전류 · 0 → 50 ms',15)+line(x+20,y,x+60,y)+(k?cap(x+110,y,false,vc):coil(x+110,y,100))+line(x+160,y,x+230,y)+dot(x+230,y,23,'#e5eceb')+`<circle cx="${x+230}" cy="${y}" r="23" fill="none" stroke="${wire}" stroke-width="2"/>`+text(x+230,y+6,'A',20)+line(x+253,y,x+290,y)+line(x+290,y,x+290,y+25)+resistor(x+290,y+65,80,true)+line(x+290,y+105,x+290,y+135)+line(x+290,y+135,x+210,y+135)+line(x+20,y,x+20,y+135)+line(x+20,y+135,x+65,y+135)+cell(x+110,y+135,false,false)+line(x+158,y+135,x+180,y+135)+button('switch','공통 스위치 전환',line(x+210,y+135,x+180,on?y+135:y+85)+dot(x+180,y+135,4)+dot(x+180,y+85,4)+box(x+165,y+65,65,95,'#ffffff01','none'))+line(x+20,y+85,x+180,y+85)+text(x+155,427,`${fmt(current*1000,2)} mA`,18,red);svg+=panel(k?'RC-right':'RL-left',g);}return {...r,svg,metrics:[metric('C 전압',fmt(vc,3),'V'),metric('L 전류',fmt(il*1000,3),'mA'),metric('C 전류',fmt(ic*1000,3),'mA'),metric('C 에너지',fmt(.5*v.C*vc*vc),'μJ'),metric('L 에너지',fmt(.5*v.L*il*il*1000),'μJ')],explanation:'동시에 전원을 연결하면 코일 전류는 점차 증가하고 축전기 전류는 처음 크다가 줄어듭니다. 각 그래프가 바로 아래 회로의 전류를 나타냅니다.',note:'5V 계단 입력의 이상적 RL/RC. 공통 스위치가 위상태를 선택합니다. 연결 후 시간은 수동 관찰 시각이며 방전은 충분히 충전된 초기 상태를 가정합니다. 원본처럼 두 접점은 함께 전환됩니다.'};});
// 63: continuous vertical logarithmic wavelength scale, selected-height wave and application.
install(63,[C('logf','주파수 log₁₀(f/Hz)',6,21,.01,14.75)],(v,t,r)=>{const y=45+(v.logf-6)/15*355,name=r.metrics[2].value,app={'전파':'라디오 · 방송','마이크로파':'레이더 · 통신','적외선':'열화상 카메라','가시광선':'눈으로 보는 빛','자외선':'살균 · 피부 영향','X선':'X선 영상','감마선':'고에너지 방사선'}[name];let svg=panel('vertical-spectrum',box(125,45,55,355,'#27353c','none',0));const bands=[[6,8.48,'#6b7f8e'],[8.48,11.48,'#586c7e'],[11.48,14.6,'#885762'],[14.6,14.9,'#6fa97c'],[14.9,16.48,'#795c9c'],[16.48,19.48,'#adb4b6'],[19.48,21,'#d0d6d8']];for(const [a,b,col]of bands)svg+=box(125,45+(a-6)/15*355,55,(b-a)/15*355,col,'none',0);for(let k=0;k<7;k++)svg+=box(125,45+(14.6-6)/15*355+k*355*.3/15/7,55,355*.3/15/7,['#d66565','#d89b5a','#e0d66b','#71ad76','#5a9bb0','#627caf','#8e6ca5'][k],'none',0);for(let exp=2;exp>=-12;exp-=1){const lf=Math.log10(299792458)-exp,yy=45+(lf-6)/15*355;if(yy>=45&&yy<=400)svg+=line(180,yy,190,yy,wire,1)+text(200,yy+4,exp>=0?`${10**exp} m`:exp>=-3?`${10**(exp+3)} mm`:exp>=-6?`${10**(exp+6)} μm`:`${10**(exp+9)} nm`,12,ink,'start');}svg+=arrow(55,y,123,y,red,4)+text(80,25,name,20,red)+panel('selected-height-wave',trace(280,y,490,24,u=>Math.sin(TAU*(1+(v.logf-6)*1.2)*u-t),blue))+panel('application',box(510,50,245,125,'#e2eae6','none')+text(632,80,app,19)+ (name==='적외선'?box(558,100,120,55,'#b96568','none')+dot(620,128,20,'#e9b66b'):name==='가시광선'?path('M560 130Q620 85 680 130Q620 175 560 130',ink,2,'#fff')+dot(620,130,17,blue):name==='전파'?path('M620 95V155M595 110Q575 125 595 140M645 110Q665 125 645 140',wire,3):path('M580 105H675V150H580Z',wire,3,'#cbd8dc')))+dragHit('logf','스펙트럼에서 위아래로 드래그',115,40,80,365,'y',6,21,45,400)+text(500,435,`${(299792458/10**v.logf).toExponential(2)} m · ${(10**v.logf).toExponential(2)} Hz`,17);return {...r,svg,note:r.note+' 스펙트럼의 위쪽은 긴 파장, 아래쪽은 짧은 파장입니다. 그림 속 눈금을 직접 드래그하거나 방향키로 선택합니다. 응용 그림은 직접 그린 단순 아이콘입니다.'};});
