function comparisonSamples(v,phase){const R=100,L=.002,C=.2e-6,w=TAU*v.frequency*1000,terms=v.wave==='square'?Array.from({length:15},(_,k)=>2*k+1):[1];let result={voltage:0,il:0,ic:0,vl:0,vc:0};for(const n of terms){const amp=v.wave==='square'?4/Math.PI/n:1,theta=n*phase,wl=w*n*L,wc=1/(w*n*C),zl=Math.hypot(R,wl),zc=Math.hypot(R,wc),il=amp/zl*Math.sin(theta-Math.atan2(wl,R)),ic=amp/zc*Math.sin(theta+Math.atan2(wc,R));result.voltage+=amp*Math.sin(theta);result.il+=il;result.ic+=ic;result.vl+=amp*wl/zl*Math.sin(theta+Math.atan2(R,wl));result.vc+=amp*wc/zc*Math.sin(theta-Math.atan2(R,wc));}return result;}
for(const id of [79,80]){let history=[],last=null,phase=0;const controls=[B('run','실행',id===79?0:1),C('frequency','주파수',1,20,.5,8,'kHz'),S('wave','공급 파형',[['sine','사인파'],['square','사각파']],'sine')];install(id,controls,(v,t)=>{if(last!==null&&t<last){history=[];phase=0;}if(+v.run&&last!==null&&t>last){const dt=Math.min(t-last,.25);for(let k=1;k<=5;k++){phase+=dt/5*v.frequency*.6;history.push(comparisonSamples(v,phase));}history=history.slice(-180);}last=t;const samples=history.length>2?history:Array.from({length:180},(_,k)=>comparisonSamples(v,k/179*TAU*2)),now=comparisonSamples(v,phase),draw=(key,x,y,w,h,color,scale=1)=>plot(x,y,w,h,u=>samples[Math.round(u*(samples.length-1))][key]*scale,color,1.2);let svg=panel('common-input',text(110,30,'공급 전압 V₀',19,green)+draw('voltage',15,50,190,105,green)+text(110,183,`${v.frequency} kHz · ${v.wave==='sine'?'사인':'사각'}파`,16));for(let k=0;k<2;k++){const x=280+k*275,component=k?'C':'L',current=k?now.ic:now.il,componentV=k?now.vc:now.vl;let g=text(x+70,30,component,21,k?blue:green);if(id===79)g+=panel('component-voltage-'+component,text(x+70,53,k?'커패시터 전압':'유도 기전력',14,blue)+draw(k?'vc':'vl',x-25,65,205,67,blue)+text(x+70,153,'전류',14,gold)+draw(k?'ic':'il',x-25,165,205,67,gold,100));else g+=draw(k?'ic':'il',x-25,50,205,105,gold,100)+text(x+70,183,'전류',16,gold);const top=id===79?290:235,bot=405,left=x-25,right=x+140;g+=line(left,top,left,(top+bot)/2-22)+dot(left,(top+bot)/2,22,'#e4ece9')+text(left,(top+bot)/2+7,'V₀',17)+line(left,(top+bot)/2+22,left,bot)+line(left,bot,x+15,bot)+resistor(x+60,bot,90)+line(x+105,bot,right,bot);if(id===79)g+=line(left,top,x+30,top)+dot(x+55,top,20,'#e3ebe6')+text(x+55,top+6,'A',17)+line(x+75,top,right,top)+line(right,top,right,top+20)+(k?cap(right,(top+bot)/2,true,componentV):coil(right,(top+bot)/2,70,true))+line(right,(top+bot)/2+35,right,bot)+line(right,top,x+195,top)+line(x+195,top,x+195,(top+bot)/2-20)+dot(x+195,(top+bot)/2,20,'#e3ebe6')+text(x+195,(top+bot)/2+6,'V',17)+line(x+195,(top+bot)/2+20,x+195,bot)+line(right,bot,x+195,bot);else g+=line(left,top,x,top)+(k?cap(x+35,top,false,componentV):coil(x+35,top,70))+line(x+70,top,x+95,top)+dot(x+115,top,20,'#e3ebe6')+text(x+115,top+6,'A',17)+line(x+135,top,right,top)+line(right,top,right,bot);if(!k)for(let a=0;a<3;a++)g+=id===79?arrow(right-15+a*15,(top+bot)/2-23*Math.sign(current||1),right-15+a*15,(top+bot)/2+23*Math.sign(current||1),green,1.5):arrow(x+35-30*Math.sign(current||1),top-22+a*16,x+35+30*Math.sign(current||1),top-22+a*16,green,1.5);g+=text(x+65,442,`I ${fmt(current*1000,2)} mA`,16,gold);svg+=panel(component+'-circuit',g);}return {svg,metrics:[metric('L 순간 전류',fmt(now.il*1000,3),'mA'),metric('C 순간 전류',fmt(now.ic*1000,3),'mA'),metric('L 순간 전압',fmt(now.vl,3),'V'),metric('C 순간 전압',fmt(now.vc,3),'V'),metric('기록 표본',history.length),metric('실행 상태',+v.run?'재생':'정지')],explanation:id===79?'왼쪽 공통 입력을 가운데 코일과 오른쪽 축전기에 함께 가합니다. 전압계는 각 소자 양단, 전류계는 회로에 직렬로 연결됩니다.':'왼쪽 공급 전압에 대한 코일 전류와 축전기 전류를 같은 높이의 세 그래프로 비교합니다. L과 C를 교체하지 않고 두 응답을 동시에 봅니다.',question:'같은 주파수에서 코일과 축전기의 전류 위상은 같나요?',answer:'아닙니다. 코일 회로 전류는 전압보다 늦고 축전기 회로 전류는 앞섭니다. 직렬 저항 때문에 차이는90도보다 작습니다.',note:'각 회로1V 피크 입력, R100Ω, L2mH 또는 C0.2μF. 사인 응답은 복소 임피던스, 사각파는 홀수 고조파15개를 합산합니다. 설정 변경 후 새 정상 상태의 표본을 기존 기록 뒤에 추가합니다. 설정 변화 자체의 과도 현상은 별도로 적분하지 않습니다. 그래프는 전압1V, 전류10mA 기준으로 표시하며 고조파 근사의 모서리 진동이 있습니다.'};},{title:id===79?'인덕터와 커패시터3 · 전압과 전류 동시 측정':'인덕터와 커패시터2 · 같은 입력, 두 전류',reset(){history=[];last=null;phase=0;},dispose(){last=null;},snapshot(){return[metric('파형 기록 표본',history.length)]},_layout:{history:()=>history.map(x=>({...x})),sample:comparisonSamples}});}
